 "content": "from collections import deque, Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    seen = set()
    frames = []

    # A frame is a monochrome 4-connected component that exactly traces a
    # rectangular perimeter, with an empty interior.
    for r in range(h):
        for c in range(w):
            color = src[r][c]
            if not color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and src[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in comp)
            r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp)
            c1 = max(x for y, x in comp)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            border = set()
            for x in range(c0, c1 + 1):
                border.add((r0, x))
                border.add((r1, x))
            for y in range(r0, r1 + 1):
                border.add((y, c0))
                border.add((y, c1))
            if set(comp) != border:
                continue
            if any(src[y][x] != 0
                   for y in range(r0 + 1, r1)
                   for x in range(c0 + 1, c1)):
                continue
            frames.append((r0, r1, c0, c1, color, border))

    frame_cells = set()
    for frame in frames:
        frame_cells.update(frame[5])
    marker_counts = Counter(src[r][c] for r in range(h) for c in range(w)
                            if src[r][c] and (r, c) not in frame_cells)

    out = [[0] * w for _ in range(h)]
    for r, c in frame_cells:
        out[r][c] = src[r][c]

    for r0, r1, c0, c1, border_color, _ in frames:
        ir, ic = r1 - r0 - 1, c1 - c0 - 1
        target_count = sum(1 for y in range(ir) for x in range(ic)
                           if (y + x) % 2 == 0)
        fill_color = next((color for color, count in marker_counts.items()
                           if count == target_count), None)
        if fill_color is None:
            continue
        for y in range(ir):
            for x in range(ic):
                if (y + x) % 2 == 0:
                    out[r0 + 1 + y][c0 + 1 + x] = fill_color
    return out
